head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[autoComplete > P > emptyValue]<br/>아이템이 선택되지 않은 상태로 처리될때 SelectBox 컴포넌트가 갖는 Value 값을 설정합니다.",
    "validation" : [        
        "emptyItem=true 인 경우에 동작합니다.",
        "SelectBox 컴포넌트가 갖는 Value 값을 문자열로 설정합니다.",
        "값을 설정하지 않으면 ''(Empty String)이 적용됩니다.",
        "메소드로 없는 아이템을 선택한 경우 SelectBox 컴포넌트의 아이템 표시 영역엔 빈값이 표시되고 Value 값은 emptyValue 속성값을 갖습니다.",
        "getValue() 메소드 실행 시 Value 값으로 설정된 emptyValue 속성값이 반환됩니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        emptyItem : true,
        emptyValue : con_emptyValue.getValue(),
    }

    let cList = $c.gcm.createCList(properties)

    // target 생성    
    $c.gcm.createBasicAutoComplete(cList);
}



scwin.btn_setValue_onclick = function (e) {
	target1.setValue(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_setSelectedIndex_onclick = function (e) {
	target1.setSelectedIndex(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_setText_onclick = function (e) {
	target1.setText("invalid");
    scwin.btn_getInfo_onclick();	
};



scwin.btn_getInfo_onclick = function (e) {
    let rtn = '';

    rtn = target1.getText();
	wf_body_bottom.getObj("scwin").setReturnValue("getText : " + rtn);

    rtn = target1.getValue();
	wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);    
};
